104	/// `cache stats` on an empty isolated cache prints the header, every
105	/// documented field with zero values, a location line, and exits 0.
106	#[test]
107	fn cache_stats_empty_shows_all_fields_and_exits_zero() {
108	    let home = TempDir::new().unwrap();
109	    let mut s = spawn_cache_isolated(&["cache", "stats"], home.path());
110	
111	    // Full strings as emitted by `show_stats` in src/cli/commands/cache.rs.
112	    s.expect("Cache Statistics:").unwrap();
113	    s.expect("  Total entries: 0").unwrap();
114	    s.expect("  Fresh: 0").unwrap();
115	    s.expect("  Expired: 0").unwrap();
116	    s.expect("  Total size: 0 bytes").unwrap();
117	    s.expect("  Location: ").unwrap();
118	    s.expect(expectrl::Eof).unwrap();
119	    assert_exit_code(&s, 0);
120	}
