125	
126	/// `cache stats` on a cache seeded with one fresh and one expired entry
127	/// reports both correctly, reports the combined byte total, and exits 0.
128	#[test]
129	fn cache_stats_with_fresh_and_expired_entries() {
130	    let home = TempDir::new().unwrap();
131	
132	    // Seed: one fresh (TTL 3600), one expired (TTL 0).
133	    let store = isolated_store(home.path());
134	    store
135	        .store("http:https://example.com", "rust-fresh", "12345", 3600)
136	        .unwrap();
137	    store
138	        .store("http:https://example.com", "rust-old", "abc", 0)
139	        .unwrap();
140	
141	    let mut s = spawn_cache_isolated(&["cache", "stats"], home.path());
142	
143	    s.expect("Cache Statistics:").unwrap();
144	    s.expect("  Total entries: 2").unwrap();
145	    s.expect("  Fresh: 1").unwrap();
146	    s.expect("  Expired: 1").unwrap();
147	    // 5 + 3 = 8 bytes.
148	    s.expect("  Total size: 8 bytes").unwrap();
149	    s.expect("  Location: ").unwrap();
150	    s.expect(expectrl::Eof).unwrap();

