    #[test]
    fn concurrent_stores_and_reads_never_corrupt() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
        use std::sync::{Arc, Barrier};

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();

        {
            let store = CacheStore::new(&root);
            store.store("http:race", "t", "seed", 3600).unwrap();
        }

        let num_writers = 4usize;
        let num_readers = 4usize;
        let barrier = Arc::new(Barrier::new(num_writers + num_readers));
        let done = Arc::new(AtomicBool::new(false));
        let errors = Arc::new(AtomicUsize::new(0));

        let mut handles = Vec::new();

        for i in 0..num_writers {
            let root = root.clone();
            let barrier = barrier.clone();
            handles.push(std::thread::spawn(move || {
                let store = CacheStore::new(&root);
                barrier.wait();
                for r in 0..200 {
                    let ch = (b'A' + i as u8) as char;
                    let content = ch.to_string().repeat(16384 + r * 64);
                    store.store("http:race", "t", &content, 3600).unwrap();
                }
            }));
        }

        for _ in 0..num_readers {
            let root = root.clone();
            let barrier = barrier.clone();
            let done = done.clone();
            let errors = errors.clone();
            handles.push(std::thread::spawn(move || {
                let store = CacheStore::new(&root);
                barrier.wait();
                while !done.load(Ordering::Acquire) {
                    match store.load("http:race", "t") {
                        Err(_) => {
                            errors.fetch_add(1, Ordering::Relaxed);
                        }
                        Ok(None) => {
                            errors.fetch_add(1, Ordering::Relaxed);
                        }
                        Ok(Some(entry)) => match store.read_content(&entry) {
                            Err(_) => {
                                errors.fetch_add(1, Ordering::Relaxed);
                            }
                            Ok(content) => {
                                if content.is_empty() {
                                    errors.fetch_add(1, Ordering::Relaxed);
                                }
                            }
                        },
                    }
                }
            }));
        }

        for h in handles.drain(..num_writers) {
            h.join().unwrap();
        }
        done.store(true, Ordering::Release);

        for h in handles {
            h.join().unwrap();
        }

        assert_eq!(
            errors.load(Ordering::Acquire),
            0,
            "Detected cache corruption during concurrent access"
        );
    }

    #[test]
    fn concurrent_stores_produce_consistent_final_state() {
        use std::sync::{Arc, Barrier};

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let barrier = Arc::new(Barrier::new(8));

        let handles: Vec<_> = (0..8)
            .map(|i| {
                let root = root.clone();
                let barrier = barrier.clone();
                std::thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    let content = format!("thread-{}-{}", i, "x".repeat(1024));
                    barrier.wait();
                    store.store("http:race", "t", &content, 3600).unwrap();
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(&root);
        let entry = store.load("http:race", "t").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        assert!(
            content.starts_with("thread-"),
            "Content corrupted: {:?}",
            &content[..content.len().min(40)]
        );
        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "Metadata size {} doesn't match content length {}",
            entry.metadata.size_bytes,
            content.len()
        );
    }
}

